\begin{equation}
\alpha_c(T) = A \cdot T^{-1/(2\beta)},
\label{eq:alpha-c-theory}
\end{equation}
where $A = (z^* \sigma / c)^{1/\beta}$ and $z^* = \Phi^{-1}(\pi^*)$ (derivation in Appendix~\ref{app:alpha_c_proof}).
